#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9

# Values this wizard produces (none of them is ever committed):
#   .env           FLY_APP, FLY_REGION, MIRROR_MCP_PATH_TOKEN (for local runs and the readout)
#   Fly secret     MIRROR_MCP_PATH_TOKEN                          (the server reads it)
#   GitHub secret  FLY_API_TOKEN                                  (deploy-dashboard.yml: fly deploy)
# The .env written here is gitignored; the secret-scan hook refuses a token in a commit.

banner "Fly.io: the hosted MCP edition (#580)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Fly account and card"
say "Fly has no free tier: a new organisation gets a \$1 trial credit, then this app costs"
say "about \$3.69/mo (shared-cpu-1x, 512 MB) + \$0.15/mo (1 GB volume)."
open_url "https://fly.io/app/sign-up"
step "Sign up (GitHub login is fine), then add a card under Billing when prompted."
pause "Press Enter once the account exists and a card is on file."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "flyctl on this machine"
if command -v flyctl >/dev/null 2>&1 || command -v fly >/dev/null 2>&1; then
  say "flyctl is already installed: $(flyctl version 2>/dev/null || fly version)"
else
  say "Install flyctl with Homebrew (the install script works too: https://fly.io/docs/flyctl/install/)."
  step "Run in another terminal:  brew install flyctl"
  pause "Press Enter once 'flyctl version' prints a version."
fi
step "Log in (opens a browser):  flyctl auth login"
pause "Press Enter once 'flyctl auth whoami' prints your email."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Region and app name"
say "Pick the region nearest the trial buyer. Short codes: ams (Amsterdam), lhr (London),"
say "fra (Frankfurt), iad (Virginia), sin (Singapore), gru (São Paulo). Full list: flyctl platform regions"
ask FLY_REGION "Region code [ams]:" || FLY_REGION="ams"
[[ -z "${FLY_REGION:-}" ]] && FLY_REGION="ams"
ask FLY_APP "App name (must match fly.toml) [mirror-market-mcp]:" || FLY_APP="mirror-market-mcp"
[[ -z "${FLY_APP:-}" ]] && FLY_APP="mirror-market-mcp"
write_env FLY_REGION "$FLY_REGION"
write_env FLY_APP "$FLY_APP"
if [[ "$FLY_REGION" != "ams" ]]; then
  warn "fly.toml says primary_region = \"ams\". Edit it to \"$FLY_REGION\" and commit that change."
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Create the app and the log volume"
say "The app is created empty; the volume holds only the question log (the DB lives in the image)."
step "Run:  flyctl apps create $FLY_APP"
step "Run:  flyctl volumes create mcp_log --app $FLY_APP --region $FLY_REGION --size 1 --yes"
note "If 'apps create' says the name is taken, pick another and update fly.toml's app = line."
pause "Press Enter once both commands succeeded."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "The secret URL path token"
say "Clients reach the server at https://$FLY_APP.fly.dev/mcp/<token>. The token is the only lock."
say "Generating one now (32 bytes, URL-safe); it is written to .env and set as a Fly secret."
MIRROR_MCP_PATH_TOKEN=$(python3 -c 'import secrets; print(secrets.token_urlsafe(32))')
write_env MIRROR_MCP_PATH_TOKEN "$MIRROR_MCP_PATH_TOKEN"
step "Run:  flyctl secrets set MIRROR_MCP_PATH_TOKEN=\"\$(grep ^MIRROR_MCP_PATH_TOKEN .env | cut -d\\' -f2)\" --app $FLY_APP --stage"
note "--stage sets it without restarting; the first deploy picks it up."
pause "Press Enter once 'flyctl secrets list --app $FLY_APP' shows MIRROR_MCP_PATH_TOKEN."
note "Not a GitHub secret: no workflow calls the token path; CI proves the edition through /health alone."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "A Fly deploy token for GitHub Actions"
say "The deploy workflow runs 'flyctl deploy' with a token scoped to this one app."
step "Run:  flyctl tokens create deploy --app $FLY_APP -x 999999h"
step "Copy the whole output, including the 'FlyV1 ' prefix and the space after it."
ask_secret FLY_API_TOKEN "Paste the deploy token:"
set_secret FLY_API_TOKEN "$FLY_API_TOKEN"
note "Not written to .env: only CI deploys; locally you are logged in already."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "First deploy by hand, with a locally built DB"
say "Proves the whole path before CI runs it. This machine needs Docker running, or use --remote-only."
if [[ ! -f data/storage/mirror_market.db ]]; then
  warn "data/storage/mirror_market.db is missing. Build it first:  python main.py --fast  (about a minute)"
  note "A --fast DB holds prices, FX and the curve only: enough to prove the deploy path, not a full edition."
  pause "Press Enter once the DB exists."
fi
step "Run:  flyctl deploy --app $FLY_APP --ha=false --yes --build-arg BUILT_AT=\"manual-\$(date -u +%FT%TZ)\""
note "First build uploads the context (~50 MB) and installs pandas; expect several minutes."
pause "Press Enter once the deploy reports the machine healthy."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Verify /health and the token path"
say "The health route is public and carries no data; the token path is the MCP endpoint."
step "Run:  curl -fsS https://$FLY_APP.fly.dev/health"
step "Expect: {\"ok\":true,\"db_built_at\":\"manual-…\",\"latest_session\":\"YYYY-MM-DD\",\"tool_count\":11}"
step "Run:  curl -s -o /dev/null -w '%{http_code}\\n' https://$FLY_APP.fly.dev/mcp     → 404"
if confirm "Did /health answer ok:true and /mcp return 404?"; then
  say "Good: the edition is live at a path only the token opens."
else
  SKIPPED+=("verify /health and /mcp 404 on https://$FLY_APP.fly.dev")
  warn "Check 'flyctl logs --app $FLY_APP' for a refusing-to-start line (a missing env var is printed by name)."
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Connect your own client as the buyer would"
say "Use the same client type as the buyer (mirror_mcp/README.md has the four)."
say "Claude Desktop: Settings → Connectors → Add custom connector → URL below, no auth."
note "The token is shown once here so you can paste it; it is otherwise only in .env and the Fly secret."
printf '\n  %shttps://%s.fly.dev/mcp/%s%s\n\n' "$BOLD" "$FLY_APP" "$MIRROR_MCP_PATH_TOKEN" "$RESET"
step "Ask three questions (a price, a crush, an origin comparison)."
step "Then:  flyctl ssh console --app $FLY_APP -C 'wc -l /data/questions.jsonl'   → 3 lines, no answer text."
pause "Press Enter when done."

finish
say "Next: merge #580 so the daily deploy publishes the edition after the site smoke, then send the"
say "buyer mirror_mcp/README.md with the URL above pasted in (#581)."
}

run_wizard "$@"; exit
